  // limits depend on it: with `true` Express would take the leftmost,
  // client-supplied entry and either limit could be bypassed by sending a header.
  //
  // The two issues each introduced a variable for the same hop count, so this is
  // applied once. Setting it twice would let the later call silently override the
  // earlier one, and a deployment that configured only `TRUST_PROXY_HOPS` would
  // lose its per-client limits without any error. `TRUST_PROXY_HOPS` has no
  // default, so an explicit value from either variable is honoured and neither
  // can quietly widen what the other trusts.
  app.set('trust proxy', environment.TRUST_PROXY_HOPS ?? environment.TRUSTED_PROXY_HOP_COUNT);
  app.use(helmet());
  app.use(
    cors({
      origin: allowedOrigins,
      credentials: true,
      exposedHeaders: BROWSER_EXPOSED_RESPONSE_HEADERS,
    }),
  );
  app.use(
    express.json({
      limit: '1mb',
      type: (request) => {
        if (request.url?.startsWith(`${API_BASE_PATH}/batches`)) {
          return false;
        }

        const contentType = request.headers['content-type'] ?? '';
        return /^application\/(?:[a-z0-9!#$&^_.+-]+\+)?json(?:;|$)/i.test(contentType);
      },
    }),
  );
  app.use(
    pinoHttp({
      autoLogging: process.env.NODE_ENV !== 'test',
      redact: ['req.headers.authorization', 'req.headers.x-api-key'],
      ...(dependencies.logger ? { logger: dependencies.logger } : {}),
    }),
  );

  app.get('/openapi.yaml', (_request, response, next) => {
    try {
      response
        .status(200)
        .set('Content-Type', 'application/yaml; charset=utf-8')
        .send(loadOpenApiSpecification());
    } catch (error) {
      next(error);
    }
  });

  app.use(API_BASE_PATH, (_request, response, next) => {
    response.setHeader('API-Version', CURRENT_API_VERSION);
    next();
  });
  app.use(apiDeprecationMiddleware);
  app.use(API_BASE_PATH, canonicalReadAuthentication);

  app.use(`${API_BASE_PATH}/health`, healthRouter);
  app.use(`${API_BASE_PATH}/auth`, createAuthRouter(verifyAccessToken, synchronizeAccount));
  app.use(API_BASE_PATH, createFixtureStatisticsRouter(fixtureStatisticsService));
  app.use(API_BASE_PATH, createParticipantAggregatesRouter(participantAggregatesService));
  app.use(API_BASE_PATH, createLeaderboardsRouter(leaderboardsService));
  app.use(API_BASE_PATH, createQueryDefinitionRouter(queryDefinitionEvaluator));
  app.use(
    API_BASE_PATH,
    createNaturalLanguageQueryRouter({
      llmClient,
      evaluator: queryDefinitionEvaluator,
      limiter: naturalLanguageQueryLimiter,
    }),
  );
  app.use(
    API_BASE_PATH,
    createSubmissionRouter(verifyAccessToken, synchronizeAccount, submissionService),
  );
  app.use(API_BASE_PATH, createBatchRouter(verifyAccessToken, synchronizeAccount, batchService));
  app.use(
    API_BASE_PATH,
    createProvenanceRouter(verifyAccessToken, synchronizeAccount, provenanceService),
  );
  app.use(
    API_BASE_PATH,
    createSubmitterAccessRouter(verifyAccessToken, synchronizeAccount, submitterAccessService),
  );
  app.use(
    API_BASE_PATH,
    createAccountDeletionRouter(verifyAccessToken, synchronizeAccount, accountDeletionService),
  );
  app.use(API_BASE_PATH, createAdminRouter(verifyAccessToken, synchronizeAccount, adminService));
  app.use(
    API_BASE_PATH,
    createApiConsumerRouter(verifyAccessToken, synchronizeAccount, apiConsumerService),
  );
  app.use(
    API_BASE_PATH,
    createApiAccessRouter(verifyAccessToken, synchronizeAccount, apiAccessService),
  );
  app.use(
    API_BASE_PATH,
    createConsumerRouter(
      publicReadService,
      fixtureStatisticsService,
      participantAggregatesService,
      consumerAuthentication,
      apiConsumerRepository,
    ),
  );
  app.use(
    API_BASE_PATH,
    createDatasetReleaseRouter(verifyAccessToken, synchronizeAccount, datasetReleaseService),
  );
  app.use(API_BASE_PATH, createPublicReadRouter(publicReadService, fixtureStatisticsService));
  app.use(API_BASE_PATH, createWeatherRouter(weatherService, fixtureWeatherService));

  app.use('/api', (request, response, next) => {
    const requestedVersion = request.path.split('/').filter(Boolean)[0];

    if (requestedVersion !== undefined && /^v\d+$/.test(requestedVersion)) {
      response.status(404).json({
        error: {
          code: 'UNSUPPORTED_API_VERSION',
          message: `API version ${requestedVersion} is not supported. Use ${API_BASE_PATH}.`,
        },
      });
      return;
    }

    next();
  });

  app.use(notFoundHandler);
  app.use(errorHandler);

  return app;
}
import { readFile } from 'node:fs/promises';
import path from 'node:path';

import { CURRENT_API_VERSION } from '@sport-analytics/contracts';
import request from 'supertest';
import { describe, expect, it, vi } from 'vitest';

import type { VerifyAccessToken } from '../../src/auth/supabase-auth';
import { createTestApp } from '../test-app';

const sourceSpecificationPath = path.resolve(
  process.cwd(),
  '..',
  '..',
  'docs',
  'api',
  'openapi.yaml',
);

describe('GET /openapi.yaml', () => {
  it('serves the authoritative OpenAPI specification anonymously', async () => {
    const verifyAccessToken = vi.fn<VerifyAccessToken>();
    const sourceSpecification = await readFile(sourceSpecificationPath, 'utf8');

    const response = await request(createTestApp(verifyAccessToken))
      .get('/openapi.yaml')
      .expect(200);

    expect(response.headers['content-type']).toMatch(/^application\/yaml(?:;|$)/);
    expect(response.text).toBe(sourceSpecification);
    expect(response.text).toContain('openapi: 3.1.0');
    expect(response.text).toContain('title: Sport Analytics API');
    expect(response.text).toContain('supportedVersions: [v1]');
    expect(verifyAccessToken).not.toHaveBeenCalled();
  }, 30_000);

  it('leaves the normal versioned API routing unchanged', async () => {
    const app = createTestApp();

    const health = await request(app).get('/api/v1/health').expect(200);
    expect(health.headers['api-version']).toBe(CURRENT_API_VERSION);

    const unsupported = await request(app).get('/api/v2/health').expect(404);
    expect(unsupported.body).toEqual({
      error: {
        code: 'UNSUPPORTED_API_VERSION',
        message: 'API version v2 is not supported. Use /api/v1.',
      },
    });
  });
});
  };
}

describe('public operations', () => {
  test('GET /health returns the documented health response', async () => {
    const response = await request(contractApp()).get('/api/v1/health').expect(200);

    contract.expectResponse(response);
  });

  test('GET /competitions returns a documented page, and 400 for an invalid limit', async () => {
    const app = contractApp({
      publicRead: {
        listCompetitions: async () => ({ data: [competition], pagination: { nextCursor: null } }),
      },
    });

    contract.expectResponse(await request(app).get('/api/v1/competitions?limit=5').expect(200));
    contract.expectResponse(await request(app).get('/api/v1/competitions?limit=0').expect(400), {
      requestIsInvalid: true,
    });
  });

  test('GET /fixtures/{fixtureId} returns a documented fixture, and 404 when it is unknown', async () => {
    const found = contractApp({ publicRead: { getFixture: async () => fixture } });
    const missing = contractApp({ publicRead: { getFixture: async () => null } });

    contract.expectResponse(await request(found).get('/api/v1/fixtures/100').expect(200));
    contract.expectResponse(await request(missing).get('/api/v1/fixtures/999').expect(404));
  });

  test('GET /fixtures/{fixtureId}/statistics returns documented fixture statistics', async () => {
    const app = contractApp({
      fixtureStatistics: {
        getFixtureStatistics: async () => fixtureStatistics,
        getFixtureStatistic: async () => null,
      },
    });

    contract.expectResponse(await request(app).get('/api/v1/fixtures/9/statistics').expect(200));
  });

  test('GET /fixtures/{fixtureId}/events/export.csv returns documented CSV', async () => {
    const app = contractApp({ publicRead: { exportFixtureEvents: async () => [event] } });

    const response = await request(app).get('/api/v1/fixtures/100/events/export.csv').expect(200);

    contract.expectResponse(response);
  });

  test('GET /dataset-releases returns documented releases, and 404 for an unknown version', async () => {
    const app = contractApp({
      datasetReleases: { listReleases: async () => [release], getRelease: async () => null },
    });

    contract.expectResponse(await request(app).get('/api/v1/dataset-releases').expect(200));
    contract.expectResponse(
      await request(app).get('/api/v1/dataset-releases/2026.09.9').expect(404),
    );
  });

  test('an unsupported API major version returns the documented UNSUPPORTED_API_VERSION error', async () => {
    const response = await request(contractApp()).get('/api/v2/health').expect(404);

    expect(response.body.error.code).toBe('UNSUPPORTED_API_VERSION');
    expect(contract.schemaProblems('/components/schemas/ApiErrorResponse', response.body)).toEqual(
      [],
    );
    expect(String((contract.document.info as { description: string }).description)).toContain(
      'UNSUPPORTED_API_VERSION',
    );
  });
});

